int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

static uint32_t rng_state;

static uint32_t rnd(void) {
  rng_state = rng_state * 1664525u + 1013904223u;
  return rng_state;
}

#define MAX_LEN (4096)
static uint8_t buf[MAX_LEN];
static size_t buf_len;

static const char *dict[] = {
  "tcp:", "udp:", "ip:", "ipv6:", "host:", "nbpf:", "@", ",", "=", "\"", "[",
  "]", "/", "cat=", "breed=", "trusted_issuer_dn:", "ip_risk_mask:",
  "host_risk_mask:", "ipv6_risk_mask:", "\n", "\r\n", "0", "9", "65535",
  "CustomProto", "www.ntop.org", "2001:db8::1", "1.2.3.4", ":", "'", " ",
  "\xff", "\x00", "-", "A", "a", "\t", "#", "443", "80"
};
#define NDICT ((int)(sizeof(dict)/sizeof(dict[0])))

static void save_current(const char *path) {
  FILE *f = fopen(path, "wb");
  if(f) {
    fwrite(buf, 1, buf_len, f);
    fclose(f);
  }
}

static void mutate(void) {
  int op = rnd() % 100;
  if(buf_len == 0 || (op < 15 && buf_len < MAX_LEN)) {
    /* insert random byte at random position */
    size_t pos = (buf_len == 0) ? 0 : (rnd() % (buf_len + 1));
    if(buf_len < MAX_LEN) {
      memmove(buf + pos + 1, buf + pos, buf_len - pos);
      buf[pos] = (uint8_t)(rnd() & 0xff);
      buf_len++;
    }
  } else if(op < 30) {
    /* delete random byte */
    size_t pos = rnd() % buf_len;
    memmove(buf + pos, buf + pos + 1, buf_len - pos - 1);
    buf_len--;
  } else if(op < 45) {
    /* insert dictionary token */
    const char *tok = dict[rnd() % NDICT];
    size_t tlen = strlen(tok);
    size_t pos = (buf_len == 0) ? 0 : (rnd() % (buf_len + 1));
    if(buf_len + tlen <= MAX_LEN) {
      memmove(buf + pos + tlen, buf + pos, buf_len - pos);
      memcpy(buf + pos, tok, tlen);
      buf_len += tlen;
    }
  } else if(op < 55) {
    /* overwrite with dictionary token */
    const char *tok = dict[rnd() % NDICT];
    size_t tlen = strlen(tok);
    size_t pos = (buf_len == 0) ? 0 : (rnd() % buf_len);
    for(size_t i = 0; i < tlen && pos + i < buf_len; i++)
      buf[pos + i] = (uint8_t)tok[i];
  } else if(op < 75) {
    /* flip/set bytes */
    size_t pos = rnd() % buf_len;
    switch(rnd() % 6) {
      case 0: buf[pos] ^= (uint8_t)(1u << (rnd() % 8)); break;
      case 1: buf[pos] = (uint8_t)(rnd() & 0xff); break;
      case 2: buf[pos] = '\n'; break;
      case 3: buf[pos] = 0; break;
      case 4: buf[pos] = ','; break;
      case 5: buf[pos] = '@'; break;
    }
  } else if(op < 85) {
    /* duplicate a block */
    size_t pos = rnd() % buf_len;
    size_t len = 1 + rnd() % 64;
    if(len > buf_len - pos) len = buf_len - pos;
    if(pos + len + len <= MAX_LEN) {
      memmove(buf + pos + len, buf + pos, buf_len - pos);
      memcpy(buf + pos, buf + pos + len, len);
      buf_len += len;
    }
  } else if(op < 92) {
    /* swap two bytes */
    size_t a = rnd() % buf_len, b = rnd() % buf_len;
    uint8_t t = buf[a]; buf[a] = buf[b]; buf[b] = t;
  } else {
    /* truncate / extend with random */
    if(buf_len > 1 && (rnd() & 1)) {
      buf_len = rnd() % buf_len;
    } else {
      while(buf_len < MAX_LEN && (rnd() & 3)) {
        buf[buf_len++] = (uint8_t)(rnd() & 0xff);
      }
    }
  }
}

int main(int argc, char **argv) {
  const char *seed_dir = argv[1];
  long iters = argc > 2 ? atol(argv[2]) : 100000;
  long seed = argc > 3 ? atol(argv[3]) : 1;
  const char *outfile = argc > 4 ? argv[4] : "/gt/current.bin";
  rng_state = (uint32_t)seed;

  /* load seeds */
  size_t nseeds = 0;
  uint8_t seeds[64][MAX_LEN];
  size_t seed_lens[64];
  DIR *d = opendir(seed_dir);
  if(d) {
    struct dirent *de;
    while((de = readdir(d)) != NULL && nseeds < 64) {
      if(de->d_name[0] == '.') continue;
      char path[1024];
      snprintf(path, sizeof(path), "%s/%s", seed_dir, de->d_name);
      FILE *f = fopen(path, "rb");
      if(!f) continue;
      fseek(f, 0, SEEK_END);
      long sz = ftell(f);
      fseek(f, 0, SEEK_SET);
      if(sz < 0 || sz > (long)MAX_LEN) sz = MAX_LEN;
      size_t rd = fread(seeds[nseeds], 1, sz, f);
      fclose(f);
      seed_lens[nseeds] = rd;
      nseeds++;
    }
    closedir(d);
  }
  if(nseeds == 0) {
    fprintf(stderr, "no seeds\n");
    return 1;
  }
  fprintf(stderr, "loaded %zu seeds, iters=%ld seed=%ld\n", nseeds, iters, seed);

  for(long iter = 0; iter < iters; iter++) {
    /* pick a seed and mutate */
    if(iter < (long)nseeds * 50) {
      size_t si = iter % nseeds;
      buf_len = seed_lens[si];
      memcpy(buf, seeds[si], buf_len);
      /* small number of mutations */
      int nm = 1 + rnd() % 4;
      for(int m = 0; m < nm; m++) mutate();
    } else {
      size_t si = rnd() % nseeds;
      buf_len = seed_lens[si];
      memcpy(buf, seeds[si], buf_len);
      int nm = 1 + rnd() % 32;
      for(int m = 0; m < nm; m++) mutate();
    }
    save_current(outfile);
    LLVMFuzzerTestOneInput(buf, buf_len);
  }
  fprintf(stderr, "done iters=%ld\n", iters);
  return 0;
}

